using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.RegularExpressions;using System.Threading.Tasks;using System.Windows.Forms;using Microsoft.Win32;
namespace THub.ACE8 {public static class AutoGamePath {
static readonly string Preference=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"NodNuatTranslator","ACE8","game-path.txt");
public static bool Supported(string p){try{return File.Exists(Path.Combine(p,"Game","Binaries","Win64","AceCombat8.exe"))&&File.Exists(Path.Combine(p,"start_protected_game.exe"));}catch{return false;}}
static void Add(HashSet<string> roots,string p){try{if(!String.IsNullOrWhiteSpace(p)){p=Path.GetFullPath(p).TrimEnd('\\','/');if((!Directory.Exists(p)||(File.GetAttributes(p)&FileAttributes.ReparsePoint)==0)&&Supported(p))roots.Add(p);}}catch{}}
public static string[] Find(){var games=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var libraries=new HashSet<string>(StringComparer.OrdinalIgnoreCase);Add(games,AppDomain.CurrentDomain.BaseDirectory);try{Add(games,File.ReadAllText(Preference));}catch{}string steam=null;try{using(var k=Registry.CurrentUser.OpenSubKey(@"Software\Valve\Steam"))if(k!=null)steam=Convert.ToString(k.GetValue("SteamPath"));}catch{}if(!String.IsNullOrWhiteSpace(steam)){libraries.Add(steam);try{foreach(Match m in Regex.Matches(File.ReadAllText(Path.Combine(steam,"steamapps","libraryfolders.vdf")),"\"path\"\\s+\"([^\"]+)\""))libraries.Add(m.Groups[1].Value.Replace(@"\\",@"\"));}catch{}}foreach(var d in DriveInfo.GetDrives())try{if(d.IsReady&&d.DriveType==DriveType.Fixed)libraries.Add(Path.Combine(d.RootDirectory.FullName,"SteamLibrary"));}catch{}foreach(var library in libraries){var apps=Path.Combine(library,"steamapps");var acf=Path.Combine(apps,"appmanifest_2288340.acf");if(!File.Exists(acf))continue;try{var match=Regex.Match(File.ReadAllText(acf),"\"installdir\"\\s+\"([^\"]+)\"");if(match.Success){string name=match.Groups[1].Value;if(name.IndexOfAny(new[]{'/','\\',':'})<0)Add(games,Path.Combine(apps,"common",name));}}catch{}}return games.OrderBy(x=>x,StringComparer.OrdinalIgnoreCase).ToArray();}
public static void Remember(string root){if(!Supported(root))return;try{Directory.CreateDirectory(Path.GetDirectoryName(Preference));File.WriteAllText(Preference,Path.GetFullPath(root));}catch{}}
public static void Bind(Form owner,TextBox path,Label status){owner.Shown+=async delegate{try{var roots=await Task.Run(()=>Find());if(owner.IsDisposed||!String.IsNullOrWhiteSpace(path.Text))return;if(roots.Length==1){path.Text=roots[0];status.Text="พบเกมแล้ว — ปิดเกมแล้วกดติดตั้งได้เลย";}else if(roots.Length>1){var selected=Choose(owner,roots);if(selected!=null)path.Text=selected;status.Text="เลือกตำแหน่งเกมแล้ว";}else status.Text="ไม่พบเกมในคลัง Steam — ใช้ปุ่มเลือกโฟลเดอร์ได้";}catch(Exception e){if(!owner.IsDisposed)status.Text="ค้นหาไม่สำเร็จ: "+e.Message;}};}
public static string Choose(IWin32Window owner,string[] roots){using(var form=new Form{Text="เลือกเกมที่ต้องการติดตั้ง",Width=740,Height=270,StartPosition=FormStartPosition.CenterParent}){var list=new ListBox{Dock=DockStyle.Fill,HorizontalScrollbar=true};list.Items.AddRange(roots);var button=new Button{Text="ใช้ตำแหน่งนี้",Height=42,Dock=DockStyle.Bottom,Enabled=false};list.SelectedIndexChanged+=delegate{button.Enabled=list.SelectedIndex>=0;};button.Click+=delegate{form.DialogResult=DialogResult.OK;};form.Controls.Add(list);form.Controls.Add(button);return form.ShowDialog(owner)==DialogResult.OK?(string)list.SelectedItem:null;}}
}}
